#!/usr/bin/env python3
import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

ROOT = Path("/root")
SMALL_RUNS_PER_YEAR = 24
BULK_RUNS_PER_YEAR = 12
SWITCH_THRESHOLD_USD = Decimal("7000")


def money(value):
    return float(Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def decimal_from(value):
    return Decimal(str(value))


def is_true(value):
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() == "true"


def load_csv(path):
    with path.open(newline="") as f:
        return list(csv.DictReader(f))


def load_in_scope_assays(manifest):
    assays = []
    for region in manifest.get("regions", []):
        for assay in region.get("assays", []):
            if assay.get("in_scope") is True:
                assays.append(assay)
    return assays


def latest_active_billing_by_label(rows):
    active_rows = [row for row in rows if is_true(row.get("is_active"))]
    by_label = {}
    for row in active_rows:
        label = row["assay_label"]
        if label not in by_label or row["effective_month"] > by_label[label]["effective_month"]:
            by_label[label] = row
    return by_label


def resolve_billing(assay, billing_by_label):
    labels = [assay["assay_name"], *assay.get("aliases", [])]
    matches = [billing_by_label[label] for label in labels if label in billing_by_label]
    if not matches:
        raise ValueError(f"No active billing row found for {assay['assay_id']}")
    return max(matches, key=lambda row: row["effective_month"])


def approved_lab_overrides(rows):
    by_assay_id = {}
    for row in rows:
        if row.get("status") != "approved":
            continue
        assay_id = row["assay_id"]
        revision = int(row["revision"])
        if assay_id not in by_assay_id or revision > int(by_assay_id[assay_id]["revision"]):
            by_assay_id[assay_id] = row
    return by_assay_id


def resolve_active_labs(assay, overrides_by_assay_id):
    override = overrides_by_assay_id.get(assay["assay_id"])
    if override is None:
        return int(assay["default_active_labs"])
    return int(override["active_labs"])


def assay_financials(assay, active_labs, payment_per_run_per_lab, carrier_cost):
    reagent_price = decimal_from(assay["reagent_price_per_1000_tests_usd"])
    small_tests = decimal_from(assay["tests_per_lab_per_run_small"])
    bulk_tests = decimal_from(assay["tests_per_lab_per_run_bulk"])
    labs = decimal_from(active_labs)

    annual_revenue_small = payment_per_run_per_lab * labs * SMALL_RUNS_PER_YEAR
    annual_revenue_bulk = payment_per_run_per_lab * labs * BULK_RUNS_PER_YEAR

    annual_reagent_cost_small = reagent_price * labs * small_tests * SMALL_RUNS_PER_YEAR / Decimal("1000")
    annual_reagent_cost_bulk = reagent_price * labs * bulk_tests * BULK_RUNS_PER_YEAR / Decimal("1000")

    annual_carrier_cost_small = carrier_cost * SMALL_RUNS_PER_YEAR
    annual_carrier_cost_bulk = carrier_cost * BULK_RUNS_PER_YEAR

    annual_margin_small = annual_revenue_small - annual_reagent_cost_small - annual_carrier_cost_small
    annual_margin_bulk = annual_revenue_bulk - annual_reagent_cost_bulk - annual_carrier_cost_bulk
    annual_margin_difference = annual_margin_bulk - annual_margin_small

    return {
        "annual_reagent_cost_small_kit_usd": money(annual_reagent_cost_small),
        "annual_reagent_cost_bulk_kit_usd": money(annual_reagent_cost_bulk),
        "annual_carrier_cost_small_kit_usd": money(annual_carrier_cost_small),
        "annual_carrier_cost_bulk_kit_usd": money(annual_carrier_cost_bulk),
        "annual_revenue_small_kit_usd": money(annual_revenue_small),
        "annual_revenue_bulk_kit_usd": money(annual_revenue_bulk),
        "annual_margin_small_kit_usd": money(annual_margin_small),
        "annual_margin_bulk_kit_usd": money(annual_margin_bulk),
        "annual_margin_difference_bulk_minus_small_usd": money(annual_margin_difference),
    }


def main():
    with (ROOT / "assay_manifest.json").open() as f:
        manifest = json.load(f)
    with (ROOT / "report_template.json").open() as f:
        template = json.load(f)

    carrier_rows = load_csv(ROOT / "carrier_cost.csv")
    billing_rows = load_csv(ROOT / "billing.csv")
    override_rows = load_csv(ROOT / "lab_overrides.csv")

    carrier_costs = {
        row["carrier_type"]: decimal_from(row["carrier_cost_usd"])
        for row in carrier_rows
    }
    billing_by_label = latest_active_billing_by_label(billing_rows)
    overrides_by_assay_id = approved_lab_overrides(override_rows)

    assay_outputs = []
    for assay in load_in_scope_assays(manifest):
        active_labs = resolve_active_labs(assay, overrides_by_assay_id)
        billing = resolve_billing(assay, billing_by_label)
        payment = decimal_from(billing["payment_per_run_per_lab_usd"])
        carrier_cost = carrier_costs[assay["carrier_type"]]
        financials = assay_financials(assay, active_labs, payment, carrier_cost)

        assay_outputs.append({
            "assay_id": assay["assay_id"],
            "assay_name": assay["assay_name"],
            "active_labs": active_labs,
            "reagent_price_per_1000_tests_usd": assay["reagent_price_per_1000_tests_usd"],
            "carrier_type": assay["carrier_type"],
            "carrier_cost_usd": money(carrier_cost),
            "payment_per_run_per_lab_usd": money(payment),
            "tests_per_lab_per_run_small": assay["tests_per_lab_per_run_small"],
            "tests_per_lab_per_run_bulk": assay["tests_per_lab_per_run_bulk"],
            **financials,
        })

    assay_outputs.sort(key=lambda item: item["assay_id"])

    total_small = sum(decimal_from(item["annual_margin_small_kit_usd"]) for item in assay_outputs)
    total_bulk = sum(decimal_from(item["annual_margin_bulk_kit_usd"]) for item in assay_outputs)
    total_difference = sum(decimal_from(item["annual_margin_difference_bulk_minus_small_usd"]) for item in assay_outputs)
    absolute_difference = abs(total_difference)

    totals = {
        "total_annual_margin_small_kit_usd": money(total_small),
        "total_annual_margin_bulk_kit_usd": money(total_bulk),
        "total_annual_margin_difference_bulk_minus_small_usd": money(total_difference),
        "absolute_total_margin_difference_usd": money(absolute_difference),
    }

    decision = "adopt_bulk_kit" if absolute_difference < SWITCH_THRESHOLD_USD else "keep_small_kit"
    if decision == "adopt_bulk_kit":
        justification = (
            "The absolute annual margin difference is below the $7,000 switch threshold, "
            "so the bulk kit can be adopted while keeping the margin impact within policy tolerance."
        )
    else:
        justification = (
            "The absolute annual margin difference meets or exceeds the $7,000 switch threshold, "
            "so the small kit should be retained to avoid an out-of-policy margin impact."
        )

    report = {
        "metadata": template["metadata"],
        "analysis": {
            "assumptions": {
                "runs_per_year_small_kit": SMALL_RUNS_PER_YEAR,
                "runs_per_year_bulk_kit": BULK_RUNS_PER_YEAR,
                "switch_threshold_usd": int(SWITCH_THRESHOLD_USD),
                "lab_override_rule": "highest approved revision per assay_id, else default_active_labs",
                "billing_rule": "latest active effective_month per assay",
            },
            "assays": assay_outputs,
            "totals": totals,
            "recommendation": {
                "decision": decision,
                "justification": justification,
            },
        },
    }

    with (ROOT / "reagent_policy_report.json").open("w") as f:
        json.dump(report, f, indent=2)

    summary_lines = [
        "# Reagent Policy Summary",
        f"Total small-kit margin (USD): {totals['total_annual_margin_small_kit_usd']:.2f}",
        f"Total bulk-kit margin (USD): {totals['total_annual_margin_bulk_kit_usd']:.2f}",
        f"Absolute difference (USD): {totals['absolute_total_margin_difference_usd']:.2f}",
        f"Final decision: {decision}",
    ]
    with (ROOT / "reagent_policy_summary.md").open("w") as f:
        f.write("\n".join(summary_lines) + "\n")


if __name__ == "__main__":
    main()

